[
  {
    "statement": "Evidence shows several approaches for mitigating environmental pollution from salmon farming.",
    "citations": []
  },
  {
    "statement": "The quality of evidence for mitigating environmental pollution from salmon farming varies.",
    "citations": []
  },
  {
    "statement": "Fallowing is the most supported action for mitigating environmental pollution from salmon farming.",
    "citations": [
      "1027"
    ]
  },
  {
    "statement": "A trial in Tasmania demonstrated that sediment community structure under Atlantic salmon cages became more similar to non-impacted sites over two fallowing cycles.",
    "citations": [
      "1027"
    ]
  },
  {
    "statement": "Integrated aquaculture systems show mixed results as a mitigation approach.",
    "citations": []
  },
  {
    "statement": "A study in Canada found that blue mussels absorbed waste from a salmon farm.",
    "citations": []
  },
  {
    "statement": "A study in Spain found no evidence that oyster and mussels fed on fish farm waste.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study in the USA reported greater growth of scallops grown next to fish farms.",
    "citations": []
  },
  {
    "statement": "A replicated, controlled study in Scotland reported enhanced algal growth when algae were placed adjacent to fish farms.",
    "citations": [
      "932"
    ]
  },
  {
    "statement": "Several potential mitigation approaches for environmental pollution from salmon farming lack evidence.",
    "citations": []
  },
  {
    "statement": "There is a lack of evidence for improving fish food and pellets to reduce waste production.",
    "citations": [
      "2192"
    ]
  },
  {
    "statement": "There is a lack of evidence for using other bioremediation methods.",
    "citations": [
      "2197"
    ]
  },
  {
    "statement": "There is a lack of evidence for modifying aquaculture practices in watersheds.",
    "citations": [
      "3172"
    ]
  },
  {
    "statement": "There is a lack of evidence for introducing water quality regulations.",
    "citations": [
      "3581"
    ]
  },
  {
    "statement": "There is a lack of evidence for cleaning wastewater before environmental release.",
    "citations": [
      "3142"
    ]
  },
  {
    "statement": "There is a lack of evidence for locating aquaculture systems in vegetated areas.",
    "citations": [
      "2189"
    ]
  }
]

[
  {
    "statement": "Several husbandry practices beyond feed and chemical treatments can improve Atlantic salmon health on farms.",
    "citations": []
  },
  {
    "statement": "Fallowing systems help reduce parasites and disease.",
    "citations": []
  },
  {
    "statement": "A study in Scotland found lower lice numbers on salmon in cages that used fallowing.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "Cage size management shows benefits for Atlantic salmon health.",
    "citations": []
  },
  {
    "statement": "Larger cages result in lower levels of amoebic gill disease compared to smaller cages.",
    "citations": [
      "742"
    ]
  },
  {
    "statement": "Aerobic training programs improve survival rates for Atlantic salmon.",
    "citations": []
  },
  {
    "statement": "Interval training is more effective than continuous training when salmon are exposed to infectious pancreatic necrosis.",
    "citations": [
      "740"
    ]
  },
  {
    "statement": "Selective breeding for disease resistance traits increases survival levels in Atlantic salmon.",
    "citations": []
  },
  {
    "statement": "A Norwegian study demonstrated that salmon bred for high resistance to infectious pancreatic necrosis showed better survival than those bred for low resistance.",
    "citations": [
      "735"
    ]
  },
  {
    "statement": "Freshwater bathing can help manage amoebic gill disease.",
    "citations": []
  },
  {
    "statement": "One study showed a reduction in gill amoebae persisting up to 10 days post-treatment with freshwater bathing.",
    "citations": [
      "739"
    ]
  },
  {
    "statement": "Probiotics and immunostimulants improve health outcomes for Atlantic salmon.",
    "citations": []
  },
  {
    "statement": "Scottish studies found increased survival in salmon fed probiotics before bacterial exposure.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Norwegian research showed that beta-glucans reduced lice infection by 28%.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Norwegian research showed that mannan oligosaccharides improved gut function in salmon.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Fallowing provides environmental benefits.",
    "citations": []
  },
  {
    "statement": "Tasmanian trials showed that sediment communities recovered to become more similar to non-impacted sites over two fallowing cycles.",
    "citations": [
      "1027"
    ]
  }
]

[
  {
    "statement": "Cleaner fish, specifically cleaner wrasse, show mixed effectiveness for sea lice control on salmon.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Two studies in Ireland found corkwing and goldskinny cleaner wrasse were as effective as chemical treatments at controlling lice infestation.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Rockcook cleaner wrasse were ineffective at preventing lice outbreaks.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Altering lighting intensity showed promise for controlling sea lice.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "A study in Norway reported lower numbers of lice on salmon kept in low intensity artificial light or natural lighting.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "The more intense the artificial light, the higher the number of lice found on fish.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "Dietary interventions using probiotics and immunostimulants showed some benefits for controlling sea lice.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Feeding salmon a diet with 28% plant-based protein reduced lice infection by 28%.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Adding beta-glucans to a salmon's diet decreased lice infection levels by a further 28% compared to controls.",
    "citations": [
      "732"
    ]
  }
]

[
  {
    "statement": "Various methods have been proposed to mitigate salmon farm impacts on benthic environments and local species.",
    "citations": []
  },
  {
    "statement": "Evidence for the effectiveness of methods proposed to mitigate salmon farm impacts is limited.",
    "citations": []
  },
  {
    "statement": "Artificial reefs have been examined as biofilters near aquaculture systems.",
    "citations": []
  },
  {
    "statement": "A controlled study in the Mediterranean Sea found similar invertebrate community composition on artificial reefs under aquaculture cages compared to control sites.",
    "citations": []
  },
  {
    "statement": "A study in the Gulf of Aqaba found similar invertebrate biomass on artificial reefs at aquaculture sites versus sites without cages.",
    "citations": []
  },
  {
    "statement": "Other proposed mitigation methods include improving fish food and pellets to reduce waste production.",
    "citations": []
  },
  {
    "statement": "Reducing aquaculture stocking densities is a proposed method to mitigate salmon farm impacts.",
    "citations": []
  },
  {
    "statement": "Locating aquaculture systems in areas with fast currents or vegetated areas is a proposed mitigation method.",
    "citations": []
  },
  {
    "statement": "Mooring aquaculture cages so the cages can move with changing currents is a proposed mitigation method.",
    "citations": []
  },
  {
    "statement": "The use of bioremediation methods is a proposed way to mitigate salmon farm impacts.",
    "citations": []
  },
  {
    "statement": "Implementing multi-trophic aquaculture systems with species from different food web levels is a proposed mitigation method.",
    "citations": []
  },
  {
    "statement": "Reducing antibiotic and pesticide use is a proposed method for mitigating salmon farm impacts.",
    "citations": []
  },
  {
    "statement": "Employing disease management strategies is a proposed method for mitigating salmon farm impacts.",
    "citations": []
  },
  {
    "statement": "Disease management strategies include freshwater bathing for amoebic gill disease.",
    "citations": []
  },
  {
    "statement": "Disease management strategies include vaccinations against various pathogens, including Aeromonas salmonicida, Yersinia ruckeri, marine flexibacteriosis, and bacterial kidney disease.",
    "citations": []
  }
]

[
  {
    "statement": "Cleaner wrasse fish are used as natural control agents for sea lice on Atlantic salmon farms.",
    "citations": []
  },
  {
    "statement": "The effectiveness of cleaner wrasse fish as a control agent for sea lice has been mixed across different species.",
    "citations": []
  },
  {
    "statement": "Lighting alterations on Atlantic salmon farms can lead to lower sea lice numbers, especially under low intensity or natural lighting.",
    "citations": []
  },
  {
    "statement": "Fallowing systems are an alternative method used to reduce parasite numbers on Atlantic salmon farms.",
    "citations": []
  },
  {
    "statement": "Dietary interventions using probiotics and immunostimulants like beta-glucans decreased sea lice infection by 28%.",
    "citations": []
  },
  {
    "statement": "Selective breeding of Atlantic salmon for resistance traits is an alternative method to control sea lice.",
    "citations": []
  }
]

[
  {
    "statement": "Available strategies for reducing environmental impact from salmon farm waste on surrounding ecosystems include integrated aquaculture systems, fallowing periods, and improved farm management practices.",
    "citations": []
  },
  {
    "statement": "Integrated aquaculture systems involve the co-cultivation of species like blue mussels, scallops, and algae alongside salmon farms to absorb waste nutrients.",
    "citations": []
  },
  {
    "statement": "Studies have shown blue mussels can absorb salmon farm waste.",
    "citations": []
  },
  {
    "statement": "Scallops demonstrate greater growth when placed adjacent to fish farms.",
    "citations": []
  },
  {
    "statement": "One study found no evidence that oysters and mussels were feeding on fish farm waste.",
    "citations": []
  },
  {
    "statement": "Fallowing strategies involve leaving salmon cages empty for periods.",
    "citations": []
  },
  {
    "statement": "Research shows that leaving salmon cages empty for periods can help sediment communities recover from aquaculture impacts.",
    "citations": []
  },
  {
    "statement": "Studies demonstrate that sediment community structure under salmon cages becomes more similar to non-impacted sites after fallowing cycles.",
    "citations": []
  },
  {
    "statement": "Additional management approaches include replacing or repairing damaged anti-predator nets to reduce environmental impacts.",
    "citations": []
  },
  {
    "statement": "Locating aquaculture systems in already impacted areas is a management approach used to minimize additional stress on pristine environments.",
    "citations": []
  },
  {
    "statement": "Evidence is limited for the strategies of replacing damaged anti-predator nets and locating aquaculture systems in already impacted areas.",
    "citations": []
  }
]

