  {
    "statement": "There is no evidence of studies from Canada evaluating alternative feed ingredients for aquaculture.",
    "citations": []
  },
  {
    "statement": "There is a lack of study evidence concerning improving fish food to reduce waste production.",
    "citations": [
      "2192"
    ]
  },
  {
    "statement": "There is a lack of study evidence concerning minimizing food waste at aquaculture systems.",
    "citations": [
      "2744"
    ]
  }
]
